class Solution { vector<string> forms(string part){vector<string> result;if(part.size()==1||part[0]!='0')result.push_back(part);for(int dot=1;dot<(int)part.size();++dot){string integer=part.substr(0,dot),fraction=part.substr(dot);if((integer.size()==1||integer[0]!='0')&&fraction.back()!='0')result.push_back(integer+"."+fraction);}return result;}public:vector<string> ambiguousCoordinates(string s){string digits=s.substr(1,s.size()-2);vector<string> answer;for(int split=1;split<(int)digits.size();++split)for(string left:forms(digits.substr(0,split)))for(string right:forms(digits.substr(split)))answer.push_back("("+left+", "+right+")");return answer;} };
